const LOCALES = ['zh', 'en'];
const DEFAULT_LOCALE = 'zh';

function normalizeLocale(locale) {
  const value = String(locale === undefined || locale === null ? '' : locale).trim().toLowerCase();
  return value.indexOf('en') === 0 ? 'en' : DEFAULT_LOCALE;
}

function lookup(dict, key) {
  let node = dict;
  const parts = String(key).split('.');
  for (let index = 0; index < parts.length; index += 1) {
    if (!node || typeof node !== 'object') return undefined;
    node = node[parts[index]];
  }
  return typeof node === 'string' ? node : undefined;
}

// 缺键每键只警告一次，避免渲染循环里刷屏。
const warnedKeys = Object.create(null);

function createTranslator(locale) {
  const normalized = normalizeLocale(locale);
  const dict = DICTS[normalized];
  const fallback = DICTS[DEFAULT_LOCALE];
  return function translate(key, vars) {
    let value = lookup(dict, key);
    if (value === undefined) {
      if (!warnedKeys[key]) {
        warnedKeys[key] = true;
        console.warn('[i18n] missing key: ' + String(key) + ' (' + normalized + ')');
      }
      // 兜底：先退到默认语言同键文案，再退空串，绝不把 key 名当文案渲染。
      value = lookup(fallback, key);
    }
    if (value === undefined) return '';
    if (!vars) return value;
    return value.replace(/\{(\w+)\}/g, function (token, name) {
      const filled = vars[name];
      return filled === undefined || filled === null ? token : String(filled);
    });
  };
}

module.exports = {
  DICTS: DICTS,
  LOCALES: LOCALES,
  DEFAULT_LOCALE: DEFAULT_LOCALE,
  normalizeLocale: normalizeLocale,
  createTranslator: createTranslator
};
